-- Local synthetic fixture only. Never run on hosted data; no provider request is made.
begin;
create temporary table gs(owner_id uuid,outsider uuid,w uuid,s uuid,c uuid,run uuid,profile uuid,test_run uuid,coordinator uuid,content uuid,quality uuid,claim1 uuid,claim2 uuid,claim3 uuid);
insert into gs values(gen_random_uuid(),gen_random_uuid(),null,null,gen_random_uuid(),gen_random_uuid(),gen_random_uuid(),gen_random_uuid(),gen_random_uuid(),gen_random_uuid(),gen_random_uuid(),gen_random_uuid(),gen_random_uuid(),gen_random_uuid());
insert into auth.users(id) select owner_id from gs union all select outsider from gs;
create function pg_temp.gsexpect(q text,n text) returns void language plpgsql as $$begin begin execute q;exception when others then if strpos(sqlerrm,n)>0 then return;else raise exception 'Unexpected: %',sqlerrm;end if;end;raise exception 'Expected %',n;end;$$;
do $$begin execute format('grant usage on schema %I to authenticated,anon,service_role',(select nspname from pg_namespace where oid=pg_my_temp_schema()));end;$$;grant all on gs to authenticated,anon,service_role;
set local role authenticated;select set_config('request.jwt.claim.sub',(select owner_id::text from gs),true);
update gs set w=(select id from public.bz_create_workspace('Stage accounting fixture'));
update gs set s=(select id from public.bz_register_site(w,'Draft pilot','external','business','https://stage-fixture.com/',null,'active',true));
select public.bz_save_site_agent_preferences(w,s,'{"brandVoice":"practical","audience":"small business owners","guidance":"Draft only"}',0) from gs;
select public.bz_mutate_knowledge(w,s,gen_random_uuid(),'save','{"title":"Approved facts","filename":"facts.md","sourceText":"Bizoveya prepares private reviewable drafts.","facts":[{"id":"f1","text":"Bizoveya prepares private reviewable drafts."}]}',0) from gs;
select public.bz_mutate_knowledge(w,s,(select id from public.bizoveya_knowledge_sources where site_id=s),'approve',null,1) from gs;
reset role;
update bizoveya_private.model_credentials set enabled=true where id='platform-gemini';
insert into bizoveya_private.model_profiles(id,slug,version,revision) select profile,'stage-fixture',1,1 from gs;
insert into bizoveya_private.model_profile_versions(profile_id,version,document,reason) select profile,1,'{"name":"Fixture Gemini","provider":"gemini","credentialRef":"platform-gemini","modelId":"fixture-model","tier":"economical","maxOutputTokens":1500,"dailyBudgetCents":100}','Synthetic stage fixture' from gs;
insert into bizoveya_private.model_profile_checks(profile_id,version,credential_id,credential_version) select profile,1,'platform-gemini',1 from gs;
insert into bizoveya_private.model_test_runs(id,profile_id,profile_version,credential_id,credential_version,claim,status,result_code,input_tokens,output_tokens,reason,finished_at) select test_run,profile,1,'platform-gemini',1,gen_random_uuid(),'passed','response_matched',20,7,'Synthetic connectivity evidence',clock_timestamp() from gs;
insert into bizoveya_private.spending_policies(profile_id,version,profile_version,document,reason) select profile,1,1,jsonb_build_object('enabled',true,'inputRateMicros',0,'outputRateMicros',0,'requestFeeMicros',0,'dailyLimitMicros',10000,'runLimitMicros',10000,'validUntil',clock_timestamp()+interval '7 days','source','https://example.com/fictional-pricing','reviewed',true),'Synthetic reviewed prices' from gs;
update bizoveya_private.agent_versions set document=jsonb_set(document,'{modelTier}','"economical"') where version=1 and agent_id in(select id from bizoveya_private.agent_definitions where kind in('coordinator','content','quality'));
update bizoveya_private.agent_definitions set preview_version=1 where kind in('coordinator','content','quality');
insert into bizoveya_private.agent_checks(agent_id,version) select id,1 from bizoveya_private.agent_definitions where kind in('coordinator','content','quality') on conflict do nothing;
insert into bizoveya_private.agent_model_bindings(agent_id,agent_version,profile_id,profile_version,credential_version,test_id,revision,enabled,reason) select a.id,1,g.profile,1,1,g.test_run,1,true,'Synthetic generation binding' from bizoveya_private.agent_definitions a cross join gs g where a.kind in('coordinator','content','quality');
-- Two currently qualified content candidates are ambiguous; a disabled candidate must not count.
insert into bizoveya_private.agent_definitions(id,slug,kind,latest_version,preview_version,revision) select content,'onboarding-second-content','content',1,1,1 from gs;
insert into bizoveya_private.agent_versions(agent_id,version,document,reason) select g.content,1,(select av.document from bizoveya_private.agent_versions av join bizoveya_private.agent_definitions a on a.id=av.agent_id where a.kind='content' and a.id<>g.content limit 1),'Synthetic duplicate content' from gs g;
insert into bizoveya_private.agent_checks(agent_id,version) select content,1 from gs;
insert into bizoveya_private.agent_model_bindings(agent_id,agent_version,profile_id,profile_version,credential_version,test_id,revision,enabled,reason) select content,1,profile,1,1,test_run,1,true,'Synthetic duplicate qualification' from gs;
set local role authenticated;select set_config('request.jwt.claim.sub',(select owner_id::text from gs),true);
do $$declare r jsonb;begin select public.bz_agency_onboarding(w,s) into r from gs;if r#>>'{current,roles,1,qualifiedCount}'<>'2' then raise exception 'Ambiguous content qualification hidden';end if;end;$$;
reset role;update bizoveya_private.agent_model_bindings set enabled=false where agent_id=(select content from gs);
set local role authenticated;select set_config('request.jwt.claim.sub',(select owner_id::text from gs),true);
select public.bz_mutate_knowledge(w,s,gen_random_uuid(),'save','{"title":"Unapproved","filename":"draft.md","sourceText":"PRIVATE_UNAPPROVED_FIXTURE","facts":[{"id":"hidden","text":"PRIVATE_UNAPPROVED_FIXTURE"}]}',0) from gs;
create temporary table ob as select public.bz_agency_onboarding(w,s) as report from gs;
grant all on ob to authenticated;
do $$begin if (select sum((r->>'qualifiedCount')::int) from ob,jsonb_array_elements(report#>'{current,roles}') r)<>3 or (select jsonb_array_length(report#>'{current,facts}') from ob)<>1 or (select report::text from ob) like '%PRIVATE_UNAPPROVED_FIXTURE%' or (select report::text from ob) like '%credentialRef%' then raise exception 'Qualification, approval or private metadata boundary failed';end if;end;$$;
create temporary table oi as select jsonb_build_object('fingerprint',report->>'fingerprint','expectedVersion',0,'note','Reviewed approved evidence; no activation.','reviewed',true) as input from ob;grant all on oi to authenticated;
select public.bz_review_agency_onboarding(w,s,input) from gs,oi;
select public.bz_review_agency_onboarding(w,s,input) from gs,oi;
select pg_temp.gsexpect(format('select public.bz_review_agency_onboarding(%L,%L,%L::jsonb)',w,s,input||'{"execute":true}'::jsonb),'bz_invalid_onboarding_review') from gs,oi;
select pg_temp.gsexpect(format('select public.bz_review_agency_onboarding(%L,%L,%L::jsonb)',w,s,jsonb_set(input,'{reviewed}','false')),'bz_invalid_onboarding_review') from gs,oi;
reset role;
update bizoveya_private.agent_model_bindings set revision=revision+1;
set local role authenticated;
-- Counts remain qualified but changing exact binding revisions must invalidate the fingerprint.
select pg_temp.gsexpect(format('select public.bz_review_agency_onboarding(%L,%L,%L::jsonb)',w,s,jsonb_set(jsonb_set(input,'{expectedVersion}','1'),'{note}','"Review stale bindings"')),'bz_onboarding_changed') from gs,oi;
reset role;update bizoveya_private.model_test_runs set finished_at=clock_timestamp()-interval '25 hours' where id=(select test_run from gs);
set local role authenticated;
update ob set report=(select public.bz_agency_onboarding(w,s) from gs);
do $$begin if (select sum((r->>'qualifiedCount')::int) from ob,jsonb_array_elements(report#>'{current,roles}') r)<>0 then raise exception 'Expired test still qualifies';end if;end;$$;
update oi set input=jsonb_build_object('fingerprint',(select report->>'fingerprint' from ob),'expectedVersion',1,'note','Reviewed expired bindings; operator renewal required.','reviewed',true);
select public.bz_review_agency_onboarding(w,s,input) from gs,oi;
select public.bz_mutate_knowledge(w,s,(select id from public.bizoveya_knowledge_sources where site_id=s and approved),'revoke',null,2) from gs;
update ob set report=(select public.bz_agency_onboarding(w,s) from gs);
do $$begin if (select jsonb_array_length(report#>'{current,facts}') from ob)<>0 or (select jsonb_array_length(report#>'{latest,snapshot,facts}') from ob)<>1 or (select jsonb_array_length(report->'history') from ob)<>2 then raise exception 'Immutable evidence/history or current approval failed';end if;end;$$;
reset role;
select pg_temp.gsexpect('update bizoveya_private.agency_onboarding_reviews set note=''Forged''','bz_immutable_onboarding_review');
insert into bizoveya_private.agency_onboarding_reviews(site_id,version,fingerprint,snapshot,note,actor_id) select site_id,n,fingerprint,snapshot,'Synthetic limit fixture',actor_id from bizoveya_private.agency_onboarding_reviews cross join generate_series(3,50) n where version=2;
set local role authenticated;
select pg_temp.gsexpect(format('select public.bz_review_agency_onboarding(%L,%L,%L::jsonb)',w,s,jsonb_build_object('fingerprint',(select report->>'fingerprint' from ob),'expectedVersion',50,'note','New bounded review','reviewed',true)),'bz_onboarding_limit') from gs;
reset role;update public.bizoveya_memberships set role='viewer' where user_id=(select owner_id from gs);
set local role authenticated;select public.bz_agency_onboarding(w,s) from gs;
select pg_temp.gsexpect(format('select public.bz_review_agency_onboarding(%L,%L,%L::jsonb)',w,s,input),'bz_forbidden') from gs,oi;
select pg_temp.gsexpect('select * from bizoveya_private.agency_onboarding_reviews','permission denied');
select set_config('request.jwt.claim.sub',(select outsider::text from gs),true);
select pg_temp.gsexpect(format('select public.bz_agency_onboarding(%L,%L)',w,s),'bz_forbidden') from gs;
reset role;
do $$begin if exists(select 1 from bizoveya_private.generation_runs where site_id=(select s from gs)) or exists(select 1 from bizoveya_private.spending_ledger) then raise exception 'Assessment started work/spending';end if;end;$$;
delete from public.bizoveya_sites where id=(select s from gs);
do $$begin if exists(select 1 from bizoveya_private.agency_onboarding_reviews where site_id=(select s from gs)) then raise exception 'Site removal retained reviews';end if;end;$$;
rollback;
